Lemma leaf_state : forall i c k ps1 t pv lv pe ce d E1 R1 E' R' (M1 M' : mem) model1 bm bd stack buf,
  is_leaf i c k ps1 t -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) ->
  CC.At (hl_segs L) c E1 R1 M1 -> HAMB i E1 M1 model1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
  PSI.contents I pv pe ce E1 M1 bm bd stack buf ->
  env_agree GT.NF E0 E' /\ know_ok RSEGS E' M' (PSM2.lcells ps1) /\ PSM2.vw i = Some (pv, pe, ce) /\
  uv E' (PB4.pv_level lv) = uv E1 (PB4.pv_level pv) /\ uv E' (PB4.pv_sb lv) = uv E1 (PB4.pv_sb pv) /\ uv E' (PB4.pv_send lv) = uv E1 (PB4.pv_send pv) /\ uv E' (PB4.pv_scend lv) = uv E1 (PB4.pv_scend pv) /\
  uv E' (PB4.pv_wend lv) = wend /\ uv E' pe = uv E1 pe /\ uv E' ce = uv E1 ce /\
  (uv E' (PB4.pv_st pv) = uv E1 (PB4.pv_st pv) /\ uv E' (PB4.pv_more pv) = uv E1 (PB4.pv_more pv) /\ uv E' (PB4.pv_level pv) = uv E1 (PB4.pv_level pv)) /\
  uv E' (PB4.pv_st lv) = match PSM2.d_st d with None => uv E1 (PB4.pv_st pv) | Some e => uv E' e end /\
  uv E' (PB4.pv_sst lv) = newv (PSM2.d_sst d) (uv E1 (PB4.pv_sst pv)) /\ uv E' (PB4.pv_nst lv) = newv (PSM2.d_nst d) (uv E1 (PB4.pv_nst pv)) /\
  uv E' (PB4.pv_more lv) = newv (PSM2.d_more d) (uv E1 (PB4.pv_more pv)) /\ uv E' (PB4.pv_done lv) = newv (PSM2.d_done d) (uv E1 (PB4.pv_done pv)) /\
  uv E' (PB4.pv_size lv) = (if PSM2.d_clr d then 0 else uv E1 (PB4.pv_size pv)) /\
  uv E' (PB4.pv_wptr lv) = uv E1 (PB4.pv_wptr pv) + PSM2.d_adv d /\ 0 <= PSM2.d_adv d <= 1 /\ uv E' (PB4.pv_wptr lv) <= wend /\
  L5.bytes_at RSEGS M' (uv E1 (PB4.pv_sb pv)) stack /\
  (PSM2.foot2 c = true -> forall a, 0 <= a < sp - 10096 -> M' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) /\
  (forall a, 0x10000 <= a < 0xf8000 -> M' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) /\
  (forall bm' bd', uv E' (PB4.pv_more lv) = PML.b2z bm' -> uv E' (PB4.pv_done lv) = PML.b2z bd' ->
     exists bufm, PML.parser_at M' P (PSI.ps_of lv pe ce E' bm' bd' stack bufm) /\ Z.of_nat (length bufm) = uv E' (PB4.pv_size lv) /\
                  (PSM2.d_clr d = false -> uv E1 (PB4.pv_st pv) = PML.ST_NUMBER -> PSM2.foot2 c = true -> bufm = buf)) /\
  CH2.den E1 (nth i G.BLS []) = [(uv E1 pe, uv E1 ce); (uv E1 (PB4.pv_sb pv), uv E1 (PB4.pv_scend pv) - uv E1 (PB4.pv_sb pv))] /\
  (forall bm' bd' bufm, PSI.ps_of lv pe ce E' bm' bd' stack bufm =
     PSS.upd (PSI.ps_of pv pe ce E1 bm bd stack buf) (uv E' (PB4.pv_st lv)) (uv E' (PB4.pv_sst lv)) (uv E' (PB4.pv_nst lv)) bm' bd' (uv E1 ce) (uv E1 pe) bufm (PB4.win_of (uv E' (PB4.pv_wptr lv)) wend)).
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S11;A1;i1;A1;o2;Y6;00;A2;k359;A1;o2;Y2;1;#0;Y3;0;P~R#0;A1;i3;A1;i1;A1;o2;#2;A1;i4;i7;A2;i11;i154;i154;A2;i11;#5;i6;A2;i11;#6;i6;A2;i11;#7;i453;A2;k355;vSCFG_P;vI;A1;k361;#9;Li;Ri128;Lc;Ri358;Lk;Ri128;Lps1;Ri148;Lt;Ri444;Lpv;Ri154;Llv;Ri154;Lpe;Ri6;Lce;Ri6;Ld;Ri453;LE1;Ri0;LR1;R#1;LE';Ri0;LR';R#1;LM1;R#3;LM';R#3;Lmodel1;Ri384;Lbm;Ri53;Lbd;Ri53;Lstack;R#4;Lbuf;R#4;LIL;RA7;k445;k446;k447;r21;r20;r19;r18;r17;LHD;RA3;i10;A1;i3;#8;A3;k454;r22;r21;r19;A2;o21;#8;A4;o13;#7;i453;A4;o13;#6;i6;A4;o13;#5;i6;A4;o13;i154;i154;r17;r16;r15;r14;r13;LHAt;RA5;k502;#10;r22;r13;r12;r9;LHA;RA16;k385;#9;A2;k386;vSCFG_P;vI;k318;A2;k319;vSCFG_P;vI;A2;k352;vSCFG_P;vI;A2;k387;vSCFG_P;vI;A2;k353;vSCFG_P;vI;A2;k322;vSCFG_P;vI;k388;A2;k389;vSCFG_P;vI;k380;A2;k390;vSCFG_P;vI;r24;r14;r10;r8;LHag;RA3;k317;A1;k422;r24;r15;r13;LHLF;RA7;i360;#10;r25;r23;r14;r13;r12;r11;LHC;RA11;k455;vSCFG_P;vI;r22;r20;r19;r17;r13;r10;r9;r8;r7;A28;k503;r28;r27;r26;r25;r24;r23;r22;r21;r20;r19;r18;r16;r15;r14;r13;r14;r12;r11;r10;r9;r8;r7;r6;r4;A8;k504;#10;r27;r25;r16;r15;r14;r13;r2;r3;r2;r1;").
